// Sequence Frame Engine — 动画级序列帧CG演出
// 与 CinematicEngine 协同：有对应镜头时用SFE，否则回退到2D特效
(async function(){const B='https://cdn.jsdelivr.net/gh/q18718859808-sketch/albina-galgame-card@v2.0.0/dist/albina-galgame-card/sfe';function lC(h){return new Promise((r,j)=>{if(document.querySelector(`link[href="${h}"]`))return r();const l=document.createElement('link');l.rel='stylesheet';l.href=h;l.onload=r;l.onerror=()=>j(new Error('CSS fail'));document.head.appendChild(l)})}function lS(s){return new Promise((r,j)=>{if(document.querySelector(`script[src="${s}"]`))return r();const t=document.createElement('script');t.src=s;t.onload=r;t.onerror=()=>j(new Error('JS fail'));document.head.appendChild(t)})}function wI(t=30000){return new Promise((r,j)=>{const e=document.querySelector('iframe[script_id]');if(e)return r(e);const tm=setTimeout(()=>j(new Error('iframe timeout')),t);const o=new MutationObserver(()=>{const f=document.querySelector('iframe[script_id]');if(f){clearTimeout(tm);o.disconnect();r(f)}});o.observe(document.body,{childList:true,subtree:true})})}try{await lC(B+'/sfe-engine.css');await lS(B+'/sfe-engine.js');await lS(B+'/sfe-director.js');const f=await wI();const eng=window.AlbinaSFE.mount(f,{});await window.AlbinaSFEDirector.registerAll(eng);window.addEventListener('message',(e)=>{const d=e.data;if(!d||!d.__albinaCinema)return;const map=window.AlbinaSFEDirector.SHOT_MAP;if(map[d.event]){window.AlbinaSFEDirector.triggerByMarker(eng,d.event)}});console.log('[SFE] 序列帧CG演出系统就绪')}catch(e){console.error('[SFE]',e)}})();

// CinematicEngine — Heaven's Feel grade cinematic overlay
// Loads after main bundle, mounts overlay + injects iframe bridge
(async function(){const B='https://cdn.jsdelivr.net/gh/q18718859808-sketch/albina-galgame-card@v2.0.0/dist/albina-galgame-card/cinema';function lC(h){return new Promise((r,j)=>{if(document.querySelector(`link[href="${h}"]`))return r();const l=document.createElement('link');l.rel='stylesheet';l.href=h;l.onload=r;l.onerror=()=>j(new Error('CSS fail'));document.head.appendChild(l)})}function lS(s){return new Promise((r,j)=>{if(document.querySelector(`script[src="${s}"]`))return r();const t=document.createElement('script');t.src=s;t.onload=r;t.onerror=()=>j(new Error('JS fail'));document.head.appendChild(t)})}function mE(){if(typeof window.AlbinaCinema==='undefined'){return new Promise(r=>{setTimeout(()=>mE().then(r),500)})}return window.AlbinaCinema.mount()}function iB(i,s){return new Promise(r=>{const t=()=>{try{const d=i.contentDocument||i.contentWindow.document;if(!d||!d.head)return false;if(i.contentWindow.__albinaCinemaBridge)return true;const sc=d.createElement('script');sc.src=s;sc.onload=()=>r(true);sc.onerror=()=>r(false);d.head.appendChild(sc);return true}catch(e){return false}};if(t())return;let a=0;const iv=setInterval(()=>{if(t()||++a>20){clearInterval(iv);r(a<=20)}},500)})}try{await Promise.all([lC(B+'/cinematic-engine.css'),lS(B+'/cinematic-engine.js')]);await mE();const f=document.querySelector('iframe[script_id]');if(f){await iB(f,B+'/cinema-iframe-bridge.js')}console.log('[Cinema] 天之杯演出系统就绪')}catch(e){console.error('[Cinema]',e)}})();
